 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    horizontal, vertical = set(), set()

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # Short rightward stroke; the terminal 1 sits one row above it.
                for cc in range(c + 1, min(c + 3, w)):
                    horizontal.add((r, cc))
                er, ec = r - 1, c + 2
                if 0 <= er < h and 0 <= ec < w:
                    out[er][ec] = 1
            elif color == 2:
                for cc in range(max(0, c - 4), c):
                    horizontal.add((r, cc))
                ec = c - 4
                if 0 <= ec < w:
                    out[r][ec] = 2
            elif color == 3:
                for rr in range(r + 1, min(r + 4, h)):
                    vertical.add((rr, c))
                er = r + 3
                if 0 <= er < h:
                    out[er][c] = 3
            elif color == 6:
                for rr in range(max(0, r - 6), r):
                    vertical.add((rr, c))
                er = r - 6
                if 0 <= er < h:
                    out[er][c] = 6

    # Draw the connecting strokes, with 5 at ordinary cells.
    for r, c in horizontal | vertical:
        if out[r][c] == 0:
            out[r][c] = 5

    # A perpendicular crossing becomes 4 and sends a diagonal down-left ray.
    crossings = horizontal & vertical
    for r, c in crossings:
        out[r][c] = 4
        rr, cc = r + 1, c - 1
        while rr < h and cc >= 0:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
